section.programlisting:
{
  files: [
    {
      url: "motd",
      destination: "/etc/issue.d/welcome.issue",
      permissions: "0644",
    },
    {
      destination: "/etc/sysusers.d/myapp.conf",
      content: |||
        # Type Name ID GECOS Home
        u      myapp - "My Application" /var/lib/myapp
      |||
    }
  ]
}
